\label{rmkdf}
{\rm (}\cite[Theorem 11, Remark 2]{CL1}, \cite[Theorems 3.3, 4.18]{FG}{\rm ).} The $d$-compatibility degree $(-\mid\mid  -)_d$ and the $f$-compatibility degree $(-\mid\mid  -)_f$ have the following properties.
\begin{itemize}
\item[(1)]  They are well-defined.


\item[(2)] The following statements are equivalent.
\begin{itemize}
\item[(i)] There exists a cluster $A_{t^\prime}$ containing both $A_{i;t_0}$ and $A_{j;t}$;

\item[(ii)] $(A_{i;t_0}\mid\mid  A_{j;t})_d\leq 0$;

\item[(iii)] $(A_{j;t}\mid\mid  A_{i;t_0})_d\leq 0$;

\item[(iv)]  $(A_{i;t_0}\mid\mid  A_{j;t})_f= 0$;

\item[(v)] $(A_{j;t}\mid\mid  A_{i;t_0})_f=0$.
\end{itemize}


\item[(3)] The following statements are equivalent.

\begin{itemize}
\item[(i)] There exists no cluster $A_{t^\prime}$ containing both $A_{i;t_0}$ and $A_{j;t}$;

\item[(ii)] $(A_{i;t_0}\mid\mid  A_{j;t})_d>0$;

\item[(iii)] $(A_{j;t}\mid\mid  A_{i;t_0})_d>0$;

\item[(iv)]  $(A_{i;t_0}\mid\mid  A_{j;t})_f>0$;

\item[(v)]$(A_{j;t}\mid\mid  A_{i;t_0})_f>0$.
\end{itemize}
\item[(4)] The following statements are equivalent.
\begin{itemize}
\item[(i)] $A_{j;t}=A_{i;t_0}$;

\item[(ii)] $(A_{i;t_0}\mid\mid  A_{j;t})_d<0$;

\item[(iii)]$(A_{j;t}\mid\mid  A_{i;t_0})_d<0$;
\item[(iv)] $(A_{i;t_0}\mid\mid  A_{j;t})_d=-1$;

\item[(v)] $(A_{j;t}\mid\mid  A_{i;t_0})_d=-1$.
\end{itemize}

\item[(5)] The following statements are equivalent.
\begin{itemize}
\item[(i)] $A_{i;t_0}\neq A_{j;t}$ and there exists a cluster $A_{t^\prime}$ containing both $A_{i;t_0}$ and $A_{j;t}$;

\item[(ii)] $(A_{i;t_0}\mid\mid  A_{j;t})_d=0$;
\item[(iii)] $(A_{j;t}\mid\mid  A_{i;t_0})_d=0$;
\end{itemize}
\end{itemize}

